    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 87-year-old male named Kenneth with advanced bilateral open-angle glaucoma is undergoing a visual assessment. His visual acuity is 20/30 bilaterally with corrective lenses. However, automated perimetry reveals significant binocular peripheral visual field loss. What is the most appropriate clinical advice regarding his driving safety?', '["Glaucoma-related visual field deficits only affect near vision, so the patient is safe to drive at high speeds on highways", "Visual field integrity is critical for driving safety; peripheral field loss increases the risk of intersection crashes and colliding with obstacles, meaning visual acuity alone is insufficient to guarantee safety, and the patient may fail state DMV licensing requirements", "The patient is safe to drive without restrictions because his visual acuity is better than 20/40, which is the sole metric used by regulatory agencies", "Prescribe a high-power prism lens to expand his visual field by 180 degrees and bypass glaucoma damage", "Advise the patient to install convex mirrors on the hood of his car to completely bypass the need for peripheral vision while driving"]'::jsonb, 1, 'Glaucoma causes progressive loss of **peripheral vision (visual field)** while preserving central visual acuity until advanced stages. A patient can easily read 20/30 on a Snellen chart but have a severe visual field deficit (tunnel vision). **Driving requires an intact visual field** (typically at least 110-120 degrees horizontally in most states) to detect hazards, traffic signs, and pedestrians from the sides. Patients with visual field deficits are at a highly elevated risk for motor vehicle collisions. Visual acuity alone does not reflect driving safety. (Ref: Hazzard''s Ch. 44; AGS Geriatrics At Your Fingertips; AMA Guide to Assessing Older Drivers)'),
